class Solution {
public:
    int longestCommonPrefix(string s,string t) {
        int i=0,n=s.size(),m=t.size();
        while (i<n && i<m && s[i]==t[i]) ++i;
        int ans=i;
        if (i==n) return ans;
        int j=i;
        while (j<m && j+1<n && s[j+1]==t[j]) ++j;
        return max(ans,j);
    }
};
